.bt-header{--navy:#004877;--ink:#252627;--cream:#F9F4EC;--sand:#F3E9D9;--sky:#3C96E7;--line:rgba(0,72,119,.16);--line2:rgba(0,72,119,.08);--mut:rgba(0,72,119,.62);--body:rgba(37,38,39,.78);--serif:"Bodoni Moda","Bodoni MT",Didot,Georgia,serif;--sans:"Jost","Century Gothic",Futura,"Helvetica Neue",Arial,sans-serif;--gut:clamp(20px,4vw,56px);--ease:cubic-bezier(.2,.7,.2,1);--ann:40px;--bar:84px;position:sticky;top:calc(var(--ann) * -1);z-index:900;font-family:var(--sans);font-size:16px;line-height:1.5;color:var(--ink);background:var(--cream);-webkit-font-smoothing:antialiased;text-align:left}
.bt-header *,.bt-header *::before,.bt-header *::after{box-sizing:border-box}
.bt-header{font-optical-sizing:none;font-variation-settings:"opsz" 30}
.bt-header a{color:inherit;text-decoration:none}
.bt-header ul{list-style:none;margin:0;padding:0}
.bt-header p{margin:0}
.bt-header img{display:block;max-width:100%}
.bt-header svg{width:20px;height:20px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.bt-header [hidden]{display:none!important}
.bt-header a:focus-visible,.bt-header label:focus-visible,.bt-header button:focus-visible,.bt-header input:focus-visible{outline:2px solid var(--sky);outline-offset:3px}
.bt-header .bt-skip{position:absolute;left:12px;top:calc(var(--ann) + 12px);z-index:60;background:var(--navy);color:#fff;padding:12px 18px;font-size:13px;font-weight:500;letter-spacing:.1em;text-transform:uppercase;opacity:0;pointer-events:none;clip-path:inset(50%)}
.bt-header .bt-skip:focus{opacity:1;pointer-events:auto;clip-path:none}

/* announcement */
.bt-header .bt-announce{height:var(--ann);background:var(--navy);color:#fff;display:flex;align-items:center;justify-content:center;font-size:11.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;white-space:nowrap;overflow:hidden}
.bt-header .bt-announce span{padding:0 22px;position:relative}
.bt-header .bt-announce span+span::before{content:"";position:absolute;left:0;top:50%;width:1px;height:12px;background:rgba(255,255,255,.4);transform:translateY(-50%)}

/* bar */
.bt-header .bt-bar{position:relative;display:flex;align-items:center;gap:clamp(16px,2vw,32px);height:var(--bar);padding:0 var(--gut);background:var(--cream);border-bottom:1px solid var(--line)}
.bt-header .bt-toggle{position:absolute;left:0;top:0;width:1px;height:1px;opacity:0;pointer-events:none;margin:0}
.bt-header .bt-nav-toggle,.bt-header .bt-sub{display:none}
.bt-header .bt-search-toggle:focus-visible~.bt-actions .bt-act-search,.bt-header .bt-nav-toggle:focus-visible~.bt-actions .bt-burger,.bt-header .bt-sub:focus-visible~.bt-sub-lbl{outline:2px solid var(--sky);outline-offset:3px}
.bt-header .bt-logo{flex-shrink:0;display:block}
.bt-header .bt-logo img{height:26px;width:auto}

/* desktop nav */
.bt-header .bt-nav{flex:1;display:flex;justify-content:center;align-self:stretch;min-width:0}
.bt-header .bt-nav-head,.bt-header .bt-nav-foot,.bt-header .bt-sub-lbl,.bt-header .bt-act.bt-burger{display:none}
.bt-header .bt-menu{display:flex;align-items:stretch;gap:clamp(12px,1.55vw,28px)}
.bt-header .bt-item{display:flex;align-items:stretch}
.bt-header .bt-item>a{display:flex;align-items:center;position:relative;font-size:12.5px;font-weight:500;letter-spacing:.14em;text-transform:uppercase;white-space:nowrap;transition:color .4s var(--ease)}
.bt-header .bt-item>a::after{content:"";position:absolute;left:0;right:0;bottom:26px;height:1px;background:var(--navy);transform:scaleX(0);transform-origin:left;transition:transform .6s var(--ease)}
.bt-header .bt-item:hover>a,.bt-header .bt-item:focus-within>a{color:var(--navy)}
.bt-header .bt-item:hover>a::after,.bt-header .bt-item:focus-within>a::after{transform:scaleX(1)}
.bt-header .bt-item-special>a{color:var(--navy)}
.bt-header .bt-item-special>a::before{content:"";width:6px;height:6px;background:var(--navy);transform:rotate(45deg);margin-right:10px}

/* mega menu */
.bt-header .bt-mega{position:absolute;left:0;right:0;top:100%;z-index:5;background:var(--cream);border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin-top:-1px;padding:44px var(--gut) 52px;opacity:0;visibility:hidden;transform:translateY(-8px);transition:opacity .4s var(--ease),transform .4s var(--ease),visibility 0s .4s}
.bt-header .bt-item:hover>.bt-mega,.bt-header .bt-item:focus-within>.bt-mega{opacity:1;visibility:visible;transform:none;transition-delay:.05s,.05s,0s}
.bt-header .bt-mega-in{max-width:1320px;margin:0 auto;display:flex;gap:clamp(32px,4vw,72px)}
.bt-header .bt-mega-col{flex:1;min-width:0}
.bt-header .bt-mega-col-2 ul{columns:2;column-gap:40px}
.bt-header .bt-mega-h{font-size:11px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--mut);margin:0 0 16px;padding-bottom:14px;border-bottom:1px solid var(--line2)}
.bt-header .bt-mega li{break-inside:avoid}
.bt-header .bt-mega li a{display:inline-block;font-family:var(--serif);font-size:20px;line-height:1.3;padding:6px 0;transition:color .3s var(--ease),transform .5s var(--ease)}
.bt-header .bt-mega li a:hover{color:var(--navy);transform:translateX(6px)}
.bt-header .bt-mega-all{display:inline-flex;align-items:center;gap:10px;margin-top:22px;font-size:11.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--navy);border-bottom:1px solid currentColor;padding-bottom:5px}
.bt-header .bt-mega-all svg{width:14px;height:14px}
.bt-header .bt-mega-card{flex:1.25;max-width:380px;margin-left:auto;display:block}
.bt-header .bt-mega-card span.bt-mega-img{display:block;aspect-ratio:4/3;overflow:hidden;background:var(--sand)}
.bt-header .bt-mega-card img{width:100%;height:100%;object-fit:cover;transition:transform 1.2s var(--ease)}
.bt-header .bt-mega-card:hover img{transform:scale(1.05)}
.bt-header .bt-mega-card b{display:block;font-family:var(--serif);font-weight:400;font-size:22px;margin-top:16px}
.bt-header .bt-mega-card small{display:block;font-size:13.5px;color:var(--body);margin-top:4px}

/* actions */
.bt-header .bt-actions{display:flex;align-items:center;gap:4px;flex-shrink:0;margin-left:auto}
.bt-header .bt-act{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:9px;height:44px;min-width:44px;padding:0 10px;font-size:13px;font-weight:500;letter-spacing:.06em;cursor:pointer;transition:color .4s var(--ease);white-space:nowrap}
.bt-header .bt-act:hover{color:var(--navy)}
.bt-header .bt-act-cart{padding-right:14px}
.bt-header .bt-act-cart .bt-act-txt{font-size:12px;letter-spacing:.14em;text-transform:uppercase}
.bt-header .bt-count{position:absolute;top:3px;left:24px;min-width:18px;height:18px;padding:0 5px;border-radius:9px;background:var(--navy);color:#fff;font-size:10.5px;font-weight:500;letter-spacing:0;display:flex;align-items:center;justify-content:center}

/* buttons */
.bt-header .bt-btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:52px;padding:0 28px;font-family:var(--sans);font-size:12.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;border:1px solid var(--navy);border-radius:2px;background:var(--navy);color:#fff;cursor:pointer;transition:background .5s var(--ease),color .5s var(--ease)}
.bt-header .bt-btn:hover{background:transparent;color:var(--navy)}
.bt-header .bt-btn-line{background:transparent;color:var(--navy)}
.bt-header .bt-btn-line:hover{background:var(--navy);color:#fff}
.bt-header .bt-btn-block{display:flex;width:100%}
.bt-header .bt-x{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;cursor:pointer;color:var(--ink);transition:color .3s,transform .6s var(--ease)}
.bt-header .bt-x:hover{color:var(--navy);transform:rotate(90deg)}

/* scrims */
.bt-header .bt-scrim{position:fixed;inset:0;background:rgba(37,38,39,.5);opacity:0;visibility:hidden;cursor:pointer;transition:opacity .5s var(--ease),visibility 0s .5s}
.bt-header .bt-scrim-search{z-index:-1}
.bt-header .bt-scrim-cart{z-index:20}
.bt-header .bt-search-toggle:checked~.bt-scrim-search,.bt-header .bt-cart-toggle:checked~.bt-scrim-cart{opacity:1;visibility:visible;transition-delay:0s}

/* search panel */
.bt-header .bt-search{position:absolute;left:0;right:0;top:100%;z-index:6;background:var(--cream);border-bottom:1px solid var(--line);padding:30px var(--gut) 38px;opacity:0;visibility:hidden;transform:translateY(-8px);transition:opacity .4s var(--ease),transform .4s var(--ease),visibility 0s .4s}
.bt-header .bt-search-toggle:checked~.bt-search{opacity:1;visibility:visible;transform:none;transition-delay:0s}
.bt-header .bt-search-in{max-width:860px;margin:0 auto}
.bt-header .bt-search form{display:flex;align-items:center;gap:12px;border-bottom:1px solid var(--navy)}
.bt-header .bt-search input[type=search]{flex:1;min-width:0;width:100%;border:0;background:transparent;font-family:var(--serif);font-size:clamp(22px,3vw,32px);line-height:1.2;padding:12px 0;color:var(--ink);outline:0;-webkit-appearance:none;appearance:none;border-radius:0}
.bt-header .bt-search input::placeholder{color:rgba(37,38,39,.4)}
.bt-header .bt-search button{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;border:0;background:transparent;color:var(--navy);cursor:pointer;padding:0}
.bt-header .bt-search-pop{display:flex;flex-wrap:wrap;align-items:center;gap:8px 22px;margin-top:18px;font-size:14px;color:var(--body)}
.bt-header .bt-search-pop b{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--mut)}
.bt-header .bt-search-pop a{border-bottom:1px solid var(--line);padding-bottom:2px;transition:color .3s,border-color .3s}
.bt-header .bt-search-pop a:hover{color:var(--navy);border-color:var(--navy)}

/* enquiry cart drawer */
.bt-header .bt-drawer{position:fixed;top:0;right:0;bottom:0;z-index:30;width:min(470px,100vw);background:var(--cream);border-left:1px solid var(--line);display:flex;flex-direction:column;clip-path:inset(0 0 0 100%);visibility:hidden;pointer-events:none;transition:clip-path .7s var(--ease),visibility 0s .7s}
.bt-header .bt-cart-toggle:checked~.bt-drawer{clip-path:inset(0);visibility:visible;pointer-events:auto;transition-delay:0s}
.bt-header .bt-drawer-head{display:flex;align-items:center;justify-content:space-between;padding:22px 20px 20px 30px;border-bottom:1px solid var(--line)}
.bt-header .bt-drawer-title{font-family:var(--serif);font-size:30px;line-height:1}
.bt-header .bt-drawer-title small{font-family:var(--sans);font-size:11px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--mut);margin-left:12px}
.bt-header .bt-flash{background:var(--navy);color:#fff;font-size:12px;font-weight:500;letter-spacing:.16em;text-transform:uppercase;padding:12px 30px;animation:btFlash .6s var(--ease) both}
@keyframes btFlash{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:none}}
.bt-header .bt-drawer-body{flex:1;overflow-y:auto;padding:0 30px;overscroll-behavior:contain}
.bt-header .bt-empty{padding:44px 0}
.bt-header .bt-empty-h{font-family:var(--serif);font-size:28px;line-height:1.15;margin-bottom:14px}
.bt-header .bt-empty p+p{font-size:15.5px;line-height:1.65;color:var(--body);margin-bottom:28px}
.bt-header .bt-line{padding:26px 0;border-bottom:1px solid var(--line)}
.bt-header .bt-line-top{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}
.bt-header .bt-line-k{font-size:10.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--mut);margin-bottom:6px}
.bt-header .bt-line-title{font-family:var(--serif);font-size:24px;line-height:1.15}
.bt-header .bt-line-title:hover{color:var(--navy)}
.bt-header .bt-line-x{flex-shrink:0;display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;margin:-6px -8px 0 0;border:0;background:transparent;color:var(--mut);cursor:pointer;padding:0}
.bt-header .bt-line-x:hover{color:var(--navy)}
.bt-header .bt-line-x svg{width:16px;height:16px}
.bt-header .bt-line-meta{font-size:14px;color:var(--body);margin-top:6px}
.bt-header .bt-line-qty{display:flex;align-items:center;flex-wrap:wrap;gap:12px 22px;margin-top:16px}
.bt-header .bt-field{display:inline-flex;align-items:center;gap:10px;font-size:11px;font-weight:500;letter-spacing:.16em;text-transform:uppercase;color:var(--mut)}
.bt-header .bt-field input[type=number]{width:96px;min-width:0;height:44px;border:1px solid var(--line);border-radius:2px;background:#fff;padding:0 12px;font-family:var(--sans);font-size:16px;color:var(--ink);letter-spacing:0}
.bt-header .bt-check{display:inline-flex;align-items:center;gap:9px;font-size:13.5px;color:var(--body);cursor:pointer}
.bt-header .bt-check input{width:17px;height:17px;accent-color:var(--navy);margin:0}
.bt-header .bt-stepper{display:inline-flex;align-items:center;border:1px solid var(--line);border-radius:2px;background:#fff}
.bt-header .bt-stepper button{width:44px;height:44px;border:0;background:transparent;font-size:18px;color:var(--navy);cursor:pointer;padding:0}
.bt-header .bt-stepper output{min-width:38px;text-align:center;font-size:16px}
.bt-header .bt-line-calc{margin-top:14px;font-size:14px;color:var(--body)}
.bt-header .bt-line-calc b{color:var(--navy);font-weight:500}
.bt-header .bt-drawer-foot{padding:22px 30px 26px;border-top:1px solid var(--line);background:var(--sand)}
.bt-header .bt-total{display:flex;align-items:baseline;justify-content:space-between;font-size:11px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--mut)}
.bt-header .bt-total b{font-family:var(--serif);font-weight:400;font-size:30px;letter-spacing:0;text-transform:none;color:var(--navy)}
.bt-header .bt-fine{font-size:13px;line-height:1.5;color:var(--body);margin:6px 0 18px}
.bt-header .bt-foot-links{display:flex;justify-content:space-between;gap:16px;margin-top:16px;font-size:11.5px;font-weight:500;letter-spacing:.16em;text-transform:uppercase;color:var(--navy)}
.bt-header .bt-foot-links a,.bt-header .bt-foot-links label{border-bottom:1px solid currentColor;padding-bottom:4px;cursor:pointer}

/* mobile dock */
.bt-header .bt-dock{display:none}

/* responsive */
@media (max-width:1679px){.bt-header .bt-act-phone .bt-act-txt{display:none}}
@media (max-width:1499px){.bt-header .bt-act-cart .bt-act-txt{display:none}.bt-header .bt-act-cart{padding-right:10px}.bt-header .bt-logo img{height:24px}}
@media (max-width:1299px){
.bt-header{--bar:68px}
.bt-header .bt-nav-toggle,.bt-header .bt-sub{display:block}
.bt-header .bt-logo img{height:24px}
.bt-header .bt-act.bt-burger{display:inline-flex}
.bt-header .bt-nav{position:fixed;inset:0;z-index:40;display:block;background:var(--cream);overflow-y:auto;padding:0 var(--gut) 48px;clip-path:inset(0 0 0 100%);visibility:hidden;pointer-events:none;transition:clip-path .7s var(--ease),visibility 0s .7s;overscroll-behavior:contain}
.bt-header .bt-nav-toggle:checked~.bt-nav{clip-path:inset(0);visibility:visible;pointer-events:auto;transition-delay:0s}
.bt-header .bt-nav-head{display:flex;align-items:center;justify-content:space-between;height:68px;border-bottom:1px solid var(--line);margin:0 calc(var(--gut) * -1);padding:0 calc(var(--gut) - 10px) 0 var(--gut);position:sticky;top:0;background:var(--cream);z-index:2}
.bt-header .bt-nav-head span{font-size:11px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--mut)}
.bt-header .bt-menu{display:block}
.bt-header .bt-item{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;border-bottom:1px solid var(--line)}
.bt-header .bt-item>a{font-family:var(--serif);font-size:26px;font-weight:400;letter-spacing:0;text-transform:none;padding:17px 0;white-space:normal}
.bt-header .bt-item>a::after{display:none}
.bt-header .bt-sub-lbl{display:inline-flex;align-items:center;justify-content:center;width:48px;height:48px;margin-right:-12px;cursor:pointer;color:var(--navy)}
.bt-header .bt-sub-lbl svg{transition:transform .5s var(--ease)}
.bt-header .bt-sub:checked~.bt-sub-lbl svg{transform:rotate(45deg)}
.bt-header .bt-mega{grid-column:1 / -1;position:static;display:none;opacity:1;visibility:visible;transform:none;border:0;margin:0;padding:2px 0 26px;background:transparent}
.bt-header .bt-sub:checked~.bt-mega{display:block}
.bt-header .bt-mega-in{display:block}
.bt-header .bt-mega-col+.bt-mega-col{margin-top:22px}
.bt-header .bt-mega-col-2 ul{columns:1}
.bt-header .bt-mega-h{margin-bottom:8px;padding-bottom:0;border:0}
.bt-header .bt-mega li a{font-size:19px;padding:7px 0}
.bt-header .bt-mega-card{display:none}
.bt-header .bt-nav-foot{display:block;padding-top:30px}
.bt-header .bt-nav-foot p{font-size:15px;line-height:1.7;color:var(--body);margin-bottom:22px}
.bt-header .bt-nav-foot p b{display:block;font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--mut);margin-bottom:6px}
.bt-header .bt-nav-foot .bt-btn{margin-bottom:12px}
}
@media (max-width:860px){.bt-header .bt-announce span:nth-child(3){display:none}}
@media (max-width:760px){
.bt-header{--bar:62px}
.bt-header .bt-logo img{height:20px}
.bt-header .bt-act-phone{display:none}
.bt-header .bt-actions{gap:0}
.bt-header .bt-dock{position:fixed;left:0;right:0;bottom:0;z-index:10;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));background:var(--cream);border-top:1px solid var(--line);padding-bottom:env(safe-area-inset-bottom)}
.bt-header .bt-dock a{position:relative;display:flex;flex-direction:column;align-items:center;gap:5px;padding:10px 4px 9px;font-size:10px;font-weight:500;letter-spacing:.16em;text-transform:uppercase;color:var(--navy)}
.bt-header .bt-dock a+a{border-left:1px solid var(--line)}
.bt-header .bt-dock .bt-count{top:4px;left:calc(50% + 4px)}
.bt-header .bt-drawer-head{padding-left:20px}
.bt-header .bt-drawer-body{padding:0 20px}
.bt-header .bt-drawer-foot{padding:20px 20px 24px}
.bt-header .bt-flash{padding:12px 20px}
}
@media (max-width:520px){.bt-header .bt-announce{font-size:10.5px;letter-spacing:.14em}.bt-header .bt-announce span{padding:0 12px}}
@media (max-width:400px){.bt-header .bt-announce span:nth-child(2){display:none}.bt-header .bt-logo img{height:17px}}
@media (max-width:359px){.bt-header{--gut:14px}.bt-header .bt-bar{gap:8px}.bt-header .bt-logo img{height:15px}.bt-header .bt-act{min-width:38px;padding:0 6px}}
@media (prefers-reduced-motion:reduce){.bt-header *,.bt-header *::before,.bt-header *::after{transition-duration:.01ms!important;animation-duration:.01ms!important}}
html:has(.bt-header .bt-nav-toggle:checked),html:has(.bt-header .bt-cart-toggle:checked),html.bt-lock{overflow:hidden}

.bt-footer{--navy:#004877;--ink:#252627;--cream:#F9F4EC;--sand:#F3E9D9;--sky:#3C96E7;--pale:#AED3F5;--line:rgba(255,255,255,.18);--soft:rgba(255,255,255,.74);--serif:"Bodoni Moda","Bodoni MT",Didot,Georgia,serif;--sans:"Jost","Century Gothic",Futura,"Helvetica Neue",Arial,sans-serif;--gut:clamp(20px,4vw,56px);--ease:cubic-bezier(.2,.7,.2,1);background:var(--navy);color:#fff;font-family:var(--sans);font-size:16px;line-height:1.6;-webkit-font-smoothing:antialiased;text-align:left}
.bt-footer *,.bt-footer *::before,.bt-footer *::after{box-sizing:border-box}
.bt-footer{font-optical-sizing:none;font-variation-settings:"opsz" 30}
.bt-footer a{color:inherit;text-decoration:none}
.bt-footer ul{list-style:none;margin:0;padding:0}
.bt-footer p{margin:0}
.bt-footer img{display:block;max-width:100%}
.bt-footer svg{width:18px;height:18px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.bt-footer a:focus-visible,.bt-footer button:focus-visible,.bt-footer input:focus-visible{outline:2px solid var(--pale);outline-offset:3px}
.bt-footer .bt-f-wrap{max-width:1432px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}

.bt-footer .bt-f-top{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:clamp(32px,6vw,96px);align-items:end;padding-top:clamp(64px,8vw,104px);padding-bottom:clamp(44px,5vw,64px);border-bottom:1px solid var(--line)}
.bt-footer .bt-f-logo img{width:min(340px,100%);height:auto}
.bt-footer .bt-f-line{font-family:var(--serif);font-size:clamp(28px,3.2vw,42px);line-height:1.12;margin-top:30px;max-width:18ch}
.bt-footer .bt-f-line em{font-style:italic;color:var(--pale)}
.bt-footer .bt-news-h{font-size:11.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--pale);margin-bottom:10px}
.bt-footer .bt-news-p{font-size:15.5px;color:var(--soft);margin-bottom:20px;max-width:44ch}
.bt-footer .bt-news{display:flex;align-items:center;border-bottom:1px solid #fff;min-width:0}
.bt-footer .bt-news input{flex:1;min-width:0;width:100%;height:54px;border:0;background:transparent;color:#fff;font-family:var(--sans);font-size:16px;padding:0;outline:0;border-radius:0}
.bt-footer .bt-news input::placeholder{color:rgba(255,255,255,.6)}
.bt-footer .bt-news button{display:inline-flex;align-items:center;gap:10px;height:54px;border:0;background:transparent;color:#fff;font-family:var(--sans);font-size:12px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;cursor:pointer;padding:0 0 0 18px;transition:color .4s var(--ease)}
.bt-footer .bt-news button:hover{color:var(--pale)}
.bt-footer .bt-news button svg{transition:transform .5s var(--ease)}
.bt-footer .bt-news button:hover svg{transform:translateX(5px)}

.bt-footer .bt-f-grid{display:grid;grid-template-columns:minmax(0,1.35fr) repeat(3,minmax(0,1fr));gap:clamp(28px,4vw,64px);padding-top:clamp(44px,5vw,64px);padding-bottom:clamp(44px,5vw,64px)}
.bt-footer .bt-f-h{font-size:11.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--pale);margin-bottom:20px}
.bt-footer .bt-f-grid li{margin-bottom:11px}
.bt-footer .bt-f-grid li a{font-size:15.5px;color:var(--soft);transition:color .3s var(--ease)}
.bt-footer .bt-f-grid li a:hover{color:#fff}
.bt-footer .bt-f-nap{font-family:var(--serif);font-size:23px;line-height:1.35;font-style:normal;margin-bottom:18px}
.bt-footer .bt-f-tel{display:inline-block;font-family:var(--serif);font-size:30px;line-height:1.1;margin-bottom:22px;border-bottom:1px solid var(--line);padding-bottom:6px;transition:border-color .4s var(--ease)}
.bt-footer .bt-f-tel:hover{border-color:#fff}
.bt-footer .bt-f-dir{display:inline-flex;align-items:center;gap:10px;font-size:12px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;border-bottom:1px solid currentColor;padding-bottom:5px}
.bt-footer .bt-f-dir svg{width:14px;height:14px}
.bt-footer .bt-f-hours{margin:0;font-size:15.5px;color:var(--soft)}
.bt-footer .bt-f-hours div{display:flex;justify-content:space-between;gap:16px;padding:9px 0;border-bottom:1px solid var(--line)}
.bt-footer .bt-f-hours div:first-child{padding-top:0}
.bt-footer .bt-f-hours dt{margin:0}
.bt-footer .bt-f-hours dd{margin:0;color:#fff;white-space:nowrap}

.bt-footer .bt-f-brands{display:flex;flex-wrap:wrap;align-items:baseline;gap:8px 26px;padding-top:26px;padding-bottom:26px;border-top:1px solid var(--line);font-family:var(--serif);font-size:18px;color:var(--soft)}
.bt-footer .bt-f-brands b{font-family:var(--sans);font-size:11.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--pale);margin-right:6px}

.bt-footer .bt-f-bot{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:14px 28px;padding-top:24px;padding-bottom:28px;border-top:1px solid var(--line);font-size:13px;color:var(--soft)}
.bt-footer .bt-f-legal{display:flex;flex-wrap:wrap;gap:6px 22px}
.bt-footer .bt-f-legal a:hover{color:#fff}
.bt-footer .bt-built{display:inline-flex;align-items:center;gap:8px;font-size:13px;color:var(--soft)}
.bt-footer .bt-built b{color:var(--pale)}
.bt-footer .bt-built-ico{width:22px;height:22px;border-radius:6px;flex-shrink:0}

@media (max-width:1023px){
.bt-footer .bt-f-top{grid-template-columns:minmax(0,1fr);align-items:start}
.bt-footer .bt-f-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media (max-width:760px){
.bt-footer{padding-bottom:calc(66px + env(safe-area-inset-bottom))}
.bt-footer .bt-f-bot{flex-direction:column;align-items:flex-start}
}
@media (max-width:520px){
.bt-footer .bt-f-grid{grid-template-columns:minmax(0,1fr)}
.bt-footer .bt-f-tel{font-size:27px}
}
@media (prefers-reduced-motion:reduce){.bt-footer *{transition-duration:.01ms!important}}
